BeforeDiscovery {
    # MT.1223's list comes from the same function the check uses, so a change to the check's list
    # is picked up here automatically. If Microsoft blocks any of these for agents, the permission
    # is dead weight in the check.
    Import-Module (Join-Path $PSScriptRoot '../../Maester.psd1') -Force
    $script:Mt1223Permissions = @(
        (& (Get-Module Maester) { Get-MtEntraAgentHighRiskGraphPermission }).Keys | Sort-Object
    )

    $snapshotPath = Join-Path $PSScriptRoot '../../internal/generated/AgentBlockedPermissions.json'

    # The snapshot is generated by build/Update-MtAgentBlockedPermissions.ps1 and
    # checked in. If it is missing, the "Snapshot file should exist" test fails.
    if (-not (Test-Path -LiteralPath $snapshotPath)) {
        $script:SnapshotMissing = $true
        $script:BlockedPermissions = @()
        return
    }

    $script:SnapshotMissing = $false
    $snapshot = Get-Content -LiteralPath $snapshotPath -Raw | ConvertFrom-Json
    $script:BlockedPermissions = $snapshot.Permissions
}

Describe 'MT.1223 permission list vs. agent blocked permissions snapshot' {

    BeforeAll {
        $snapshotPath = Join-Path $PSScriptRoot '../../internal/generated/AgentBlockedPermissions.json'

        if (-not (Test-Path -LiteralPath $snapshotPath)) {
            return
        }

        $snapshot = Get-Content -LiteralPath $snapshotPath -Raw | ConvertFrom-Json
        $script:BlockedPermissions = $snapshot.Permissions
    }

    It 'Snapshot file should exist' {
        Test-Path -LiteralPath (Join-Path $PSScriptRoot '../../internal/generated/AgentBlockedPermissions.json') | Should -BeTrue -Because `
            'AgentBlockedPermissions.json must be checked in. Run build/Update-MtAgentBlockedPermissions.ps1 to generate it.'
    }

    It 'MT.1223 permission list should not be empty' -ForEach @(@{ PermissionCount = $script:Mt1223Permissions.Count }) {
        $PermissionCount | Should -BeGreaterThan 0 -Because `
            'Get-MtEntraAgentHighRiskGraphPermission returned no permissions, so the drift check below would run nothing.'
    }

    It 'Snapshot file should have at least 50 permissions' -Skip:($script:SnapshotMissing) {
        $script:BlockedPermissions.Count | Should -BeGreaterOrEqual 50
    }

    It '<permission> should not be blocked for Application in the snapshot' -Skip:($script:SnapshotMissing) -ForEach @(
        $script:Mt1223Permissions | ForEach-Object { @{ Permission = $_ } }
    ) {
        $entry = $script:BlockedPermissions | Where-Object { $_.Permission -eq $permission }
        if ($null -eq $entry) {
            # Permission isn't in the blocked list at all, which means it's grantable. Pass.
            $true | Should -BeTrue
        } else {
            # If it IS in the blocked list with Application = true, it can't be granted to agents.
            # That means MT.1223 is checking a permission that can never fire.
            $entry.Application | Should -BeFalse -Because `
                "'$permission' is now blocked for Application by Microsoft (per AgentBlockedPermissions.json). It should be removed from MT.1223's curated list because agents can no longer hold it."
        }
    }
}
